// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.vectorbench;

/** Standalone scalar/vector equality oracle covering empty inputs, full blocks, masked tails, and unsigned IDs. */
public final class VectorAdjacencyKernelOracle {
	private VectorAdjacencyKernelOracle() {
	}

	public static void main(String[] args) {
		int[] lengths = { 0, 1, 2, 3, 7, 255, 256, 257, 8191, 8192, 8193, 65536 };
		for (int length : lengths) {
			AdjacencyKernelBenchmarkData data = new AdjacencyKernelBenchmarkData();
			data.initialize(length);
			check("unsignedRangeCount", length,
					ScalarAdjacencyKernelBenchmark.unsignedRangeCount(data.values, data.lower, data.upper),
					VectorAdjacencyKernelBenchmark.unsignedRangeCount(data.values, data.lower, data.upper));
			check("distinctTransitions", length,
					ScalarAdjacencyKernelBenchmark.distinctTransitions(data.values),
					VectorAdjacencyKernelBenchmark.distinctTransitions(data.values));
			check("multiplicitySum", length,
					ScalarAdjacencyKernelBenchmark.multiplicitySum(data.multiplicities),
					VectorAdjacencyKernelBenchmark.multiplicitySum(data.multiplicities));
			check("denseIntersectionPopcount", length,
					ScalarAdjacencyKernelBenchmark.denseIntersectionPopcount(data.leftMask, data.rightMask),
					VectorAdjacencyKernelBenchmark.denseIntersectionPopcount(data.leftMask, data.rightMask));
			check("countEqual", length, ScalarAdjacencyKernelBenchmark.countEqual(data.filterValues, 1L),
					VectorAdjacencyKernelBenchmark.countEqual(data.filterValues, 1L));
			check("countEqualColumns", length,
					ScalarAdjacencyKernelBenchmark.countEqualColumns(data.filterValues, data.otherFilterValues),
					VectorAdjacencyKernelBenchmark.countEqualColumns(data.filterValues, data.otherFilterValues));
			checkSelection("selectEqual", length, data,
					ScalarAdjacencyKernelBenchmark.selectEqual(data.filterValues, 1L, data.selectionTarget), true);
			checkSelection("selectUnsignedRange", length, data,
					ScalarAdjacencyKernelBenchmark.selectUnsignedRange(data.values, data.lower, data.upper,
							data.selectionTarget),
					false);
			check("hashDenseThreeColumns", length,
					ScalarAdjacencyKernelBenchmark.hashDenseThreeColumns(data.hashColumn0, data.hashColumn1,
							data.hashColumn2, new long[length]),
					VectorAdjacencyKernelBenchmark.hashDenseThreeColumns(data.hashColumn0, data.hashColumn1,
							data.hashColumn2, new long[length]));
			check("hashIndirectThreeColumns", length,
					ScalarAdjacencyKernelBenchmark.hashIndirectThreeColumns(data.hashColumn0, data.hashColumn1,
							data.hashColumn2, data.indirect, new long[length]),
					VectorAdjacencyKernelBenchmark.hashIndirectThreeColumns(data.hashColumn0, data.hashColumn1,
							data.hashColumn2, data.indirect, new long[length]));
			check("countUniformIriKind", length,
					ScalarAdjacencyKernelBenchmark.countTermKind(data.uniformIriIds, 1),
					VectorAdjacencyKernelBenchmark.countTermKind(data.uniformIriIds, 1));
			check("countMixedLiteralKind", length,
					ScalarAdjacencyKernelBenchmark.countTermKind(data.mixedTermIds, 2),
					VectorAdjacencyKernelBenchmark.countTermKind(data.mixedTermIds, 2));
			check("classifyUniformIriTraits", length,
					ScalarAdjacencyKernelBenchmark.classifyColumnTraits(data.uniformIriIds),
					VectorAdjacencyKernelBenchmark.classifyColumnTraits(data.uniformIriIds));
			check("classifyMixedLiteralTraits", length,
					ScalarAdjacencyKernelBenchmark.classifyColumnTraits(data.mixedTermIds),
					VectorAdjacencyKernelBenchmark.classifyColumnTraits(data.mixedTermIds));
			check("classifyUniformCoreLiteralTraits", length,
					ScalarAdjacencyKernelBenchmark.classifyColumnTraits(data.uniformCoreLiteralIds),
					VectorAdjacencyKernelBenchmark.classifyColumnTraits(data.uniformCoreLiteralIds));
			check("uniformCoreLiteralDatatype", length,
					ScalarAdjacencyKernelBenchmark.uniformCoreLiteralDatatype(data.uniformCoreLiteralIds) ? 1L : 0L,
					VectorAdjacencyKernelBenchmark.uniformCoreLiteralDatatype(data.uniformCoreLiteralIds) ? 1L : 0L);
			check("saturatedMultiplicitySum", length,
					ScalarAdjacencyKernelBenchmark.saturatedMultiplicitySum(data.multiplicities),
					VectorAdjacencyKernelBenchmark.saturatedMultiplicitySum(data.multiplicities));
			check("orderedUniqueDomain", length,
					ScalarAdjacencyKernelBenchmark.orderedUnique(data.orderedIds, true) ? 1L : 0L,
					VectorAdjacencyKernelBenchmark.orderedUnique(data.orderedIds, true) ? 1L : 0L);
			checkDecode("decodeUnsignedBytes", length, data, 1);
			checkDecode("decodeUnsignedShorts", length, data, 2);
			checkDecode("decodeUnsignedInts", length, data, 4);
			checkDecode("decodeLongs", length, data, 8);
			check("countParserStructuralBytes", length,
					ScalarAdjacencyKernelBenchmark.countParserStructuralBytes(data.parserBytes),
					VectorAdjacencyKernelBenchmark.countParserStructuralBytes(data.parserBytes));
			check("findLiteralDelimiter", length,
					ScalarAdjacencyKernelBenchmark.findLiteralDelimiter(data.literalBytes, 0, length),
					VectorAdjacencyKernelBenchmark.findLiteralDelimiter(data.literalBytes, 0, length));
		}
		long[] overflow = { Long.MAX_VALUE - 1, 2L };
		check("saturatedMultiplicityOverflow", overflow.length,
				ScalarAdjacencyKernelBenchmark.saturatedMultiplicitySum(overflow),
				VectorAdjacencyKernelBenchmark.saturatedMultiplicitySum(overflow));
		System.out.println("VECTOR_ORACLE_PASS lanes=" + VectorAdjacencyKernelBenchmark.laneCount());
	}

	private static void checkSelection(String operation, int length, AdjacencyKernelBenchmarkData data,
			int scalarCount, boolean equality) {
		int[] scalar = data.selectionTarget.clone();
		int[] vector = new int[length];
		int vectorCount = equality
				? VectorAdjacencyKernelBenchmark.selectEqual(data.filterValues, 1L, vector)
				: VectorAdjacencyKernelBenchmark.selectUnsignedRange(data.values, data.lower, data.upper, vector);
		check(operation + "Count", length, scalarCount, vectorCount);
		for (int i = 0; i < scalarCount; i++) {
			check(operation + "Position" + i, length, scalar[i], vector[i]);
		}
	}

	private static void checkDecode(String operation, int length, AdjacencyKernelBenchmarkData data, int width) {
		long[] scalar = new long[length];
		long[] vector = new long[length];
		switch (width) {
		case 1 -> {
			ScalarAdjacencyKernelBenchmark.decodeUnsignedBytes(data.packedBytes, 0x1000L, scalar);
			VectorAdjacencyKernelBenchmark.decodeUnsignedBytes(data.packedBytes, 0x1000L, vector);
		}
		case 2 -> {
			ScalarAdjacencyKernelBenchmark.decodeUnsignedShorts(data.packedShorts, 0x1000L, scalar);
			VectorAdjacencyKernelBenchmark.decodeUnsignedShorts(data.packedShorts, 0x1000L, vector);
		}
		case 4 -> {
			ScalarAdjacencyKernelBenchmark.decodeUnsignedInts(data.packedInts, 0x1000L, scalar);
			VectorAdjacencyKernelBenchmark.decodeUnsignedInts(data.packedInts, 0x1000L, vector);
		}
		default -> {
			ScalarAdjacencyKernelBenchmark.decodeLongs(data.values, 0x1000L, scalar);
			VectorAdjacencyKernelBenchmark.decodeLongs(data.values, 0x1000L, vector);
		}
		}
		for (int i = 0; i < length; i++) {
			check(operation + "Lane" + i, length, scalar[i], vector[i]);
		}
	}

	private static void check(String operation, int length, long scalar, long vector) {
		if (scalar != vector) {
			throw new AssertionError(operation + " length=" + length + " scalar=" + scalar + " vector=" + vector);
		}
	}
}
